class Solution {
public:
    int countElementsWithKGreater(vector<int>& nums, int k) {
        if (k == 0) return nums.size();
        vector<int> a = nums;
        sort(a.begin(), a.end());
        int t = a[a.size() - k];
        return lower_bound(a.begin(), a.end(), t) - a.begin();
    }
};

