class Solution {
    public int countElementsWithKGreater(int[] nums, int k) {
        if (k == 0) return nums.length;
        int[] a = nums.clone();
        Arrays.sort(a);
        int t = a[a.length - k];
        int lo = 0;
        while (lo < a.length && a[lo] < t) lo++;
        return lo;
    }
}

