var countElementsWithKGreater = function(nums, k) {
    if (k === 0) return nums.length;
    const a = [...nums].sort((x, y) => x - y);
    const t = a[a.length - k];
    let lo = 0;
    while (lo < a.length && a[lo] < t) lo++;
    return lo;
};
